{
  "name": "350型多通道温度控制器",
  "name_en": "Lake Shore Model 350 Temperature Controller",
  "manufacturer": "Lake Shore Cryotronics",
  "description": "一款多通道温度控制器，可读取多个温度传感器输入并驱动加热器输出，用于温度设定值保持、按斜坡升降温以及加热功率调节，常用于实验中的样品温度监测与稳定控制。",
  "description_en": "A multi-channel temperature controller that reads multiple temperature sensor inputs and drives heater outputs for setpoint regulation, ramped temperature changes, and heater power control. It is commonly used for sample temperature monitoring and stabilization in laboratory experiments.",
  "tag_hints": [
    "temperature control",
    "multi-sensor readout",
    "heater output control",
    "setpoint ramping",
    "sample temperature stabilization",
    "laboratory instrumentation"
  ],
  "actions": [
    {
      "action_name": "auto-close",
      "description": "安全关闭加热器并关闭设备连接",
      "description_en": "Safely shut down the heater and close the device connection."
    },
    {
      "action_name": "auto-reset_and_clear",
      "description": "复位设备并清除状态寄存器",
      "description_en": "Reset the instrument and clear the status registers."
    },
    {
      "action_name": "auto-set_heater_range",
      "description": "设置加热器输出量程",
      "description_en": "Set the heater output range."
    },
    {
      "action_name": "auto-set_setpoint",
      "description": "设置温度设定值",
      "description_en": "Set the temperature setpoint."
    },
    {
      "action_name": "auto-setup_heater",
      "description": "配置加热器参数",
      "description_en": "Configure the heater parameters."
    },
    {
      "action_name": "auto-setup_ramp",
      "description": "配置设定值斜坡速率",
      "description_en": "Configure the setpoint ramp rate."
    },
    {
      "action_name": "auto-get_heater_output",
      "description": "获取加热器输出百分比",
      "description_en": "Get the heater output percentage."
    },
    {
      "action_name": "auto-get_temperature",
      "description": "获取传感器温度",
      "description_en": "Get the sensor temperature."
    }
  ]
}

